arguments.command:
cd /tmp && cat > slack_find.py <<'EOF'
import json, subprocess, sys

def call(endpoint, params):
    d = {'token':'<TOKEN>'}
    d.update(params)
    out = subprocess.run(['curl','-sS','-X','POST',f'https://slack.com/api/{endpoint}?token=<TOKEN>'] + [f'{k}={v}' for k,v in params.items() if v is not None], capture_output=True, text=True)
    return json.loads(out.stdout)

cursor = None
pages = 0
found = []
while pages < 10:
    params = {'channel':'C_LAUNCH','limit':'100','oldest':'0'}
    if cursor:
        params['cursor'] = cursor
    else:
        params.pop('oldest')
    d = call('conversations.history', params)
    if not d.get('ok'):
        print('ERR', d); break
    msgs = d.get('messages',[])
    for m in msgs:
        txt = m.get('text','')
        if 'checklist' in txt.lower():
            found.append((m.get('ts'), m.get('user'), txt.replace('\n',' / ')[:150], m.get('reactions',[])))
    cursor = d.get('response_metadata',{}).get('next_cursor')
    pages += 1
    if not cursor:
        break

for f in found:
    print(f)
print('pages:', pages)
EOF
python3 slack_find.py

